import json
import heapq

map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])

def solve_safari_path(map_id, start_x, start_y, target_x, target_y):
    width, height = 30, 25
    if map_id == "0_218": # North is 40x36
        width, height = 40, 36
    elif map_id == "0_220": # Center is 30x27
        width, height = 30, 27

    def is_plateau_tile(mx, my):
        if map_id == "0_219": # West
            if 6 <= mx <= 10 and 16 <= my <= 19:
                return True
            if 11 <= mx <= 16 and 6 <= my <= 19:
                return True
            if mx == 17 and 6 <= my <= 17:
                return True
            if 18 <= mx <= 22 and 14 <= my <= 17:
                return True
            return False
        elif map_id == "0_217": # East
            if 11 <= mx <= 22 and 6 <= my <= 20:
                return True
            if 11 <= mx <= 18 and 4 <= my <= 5:
                return True
            return False
        elif map_id == "0_218": # North
            # Corrected Western Plateau geometry
            if 15 <= mx <= 18 and 24 <= my <= 27:
                return True
            if 15 <= mx <= 24 and 20 <= my <= 23:
                return True
            # Eastern Plateau
            if 28 <= mx <= 38 and 24 <= my <= 27:
                return True
            if 37 <= mx <= 38 and 15 <= my <= 23:
                return True
            if 34 <= mx <= 36 and 15 <= my <= 19:
                return True
            return False
        return False

    static_ground_obstacles = set()

    if map_id == "0_219": # West
        for x in range(10, 14):
            for y in range(8, 12):
                static_ground_obstacles.add((x, y))
        static_ground_obstacles.add((12, 12))
        for x in range(2, 10):
            for y in range(10, 14):
                static_ground_obstacles.add((x, y))
        for y in range(11, 16):
            static_ground_obstacles.add((14, y))
            static_ground_obstacles.add((15, y))

        # Correctly block Column 24 and Column 25 tree boundaries
        for y in range(0, 14):
            static_ground_obstacles.add((24, y))
        static_ground_obstacles.add((25, 0))
        static_ground_obstacles.add((25, 1))

        for y in range(14, 18):
            static_ground_obstacles.add((23, y))
        static_ground_obstacles.add((1, 13))
        static_ground_obstacles.add((1, 14))
        static_ground_obstacles.add((1, 15))
        static_ground_obstacles.add((4, 16))
        static_ground_obstacles.add((4, 17))
        static_ground_obstacles.add((4, 18))
        static_ground_obstacles.add((4, 19))
        for y in range(height):
            static_ground_obstacles.add((0, y))

    elif map_id == "0_217": # East
        for x in range(5, 9):
            for y in range(21, 24):
                static_ground_obstacles.add((x, y))
        for x in range(0, 11):
            static_ground_obstacles.add((x, 6))
        for x in range(16, 20):
            for y in range(16, 18):
                static_ground_obstacles.add((x, y))
        static_ground_obstacles.add((19, 4))
        static_ground_obstacles.add((19, 5))
        static_ground_obstacles.add((19, 6))

    elif map_id == "0_218": # North
        # Fences and walls at bottom left/middle
        for x in range(10, 20):
            static_ground_obstacles.add((x, 34))
            static_ground_obstacles.add((x, 35))

        # Column 16 tree wall (Rows 11 to 19)
        for y in range(11, 20):
            static_ground_obstacles.add((16, y))

        # Row 11 horizontal tree wall (Columns 16 to 23)
        for x in range(16, 24):
            static_ground_obstacles.add((x, 11))

        # Add solid wooden fence on Column 36 (Rows 15 to 23)
        for y in range(15, 24):
            static_ground_obstacles.add((36, y))

        # Add solid cliff wall on Column 25 (Rows 20 to 23)
        for y in range(20, 24):
            static_ground_obstacles.add((25, y))

        # Add solid cliff walls on Row 23 (Columns 23 to 25)
        for x in range(23, 26):
            static_ground_obstacles.add((x, 23))

        # Column 19 tree/building corner (Rows 33 to 35)
        for y in range(33, 36):
            static_ground_obstacles.add((19, y))

        # Blocked cliff edges from Row 24 (Columns 26-27)
        static_ground_obstacles.add((26, 24))
        static_ground_obstacles.add((27, 24))

        # Eastern rocks in Safari Zone North (Map 0_218)
        for x in [38, 39]:
            for y in [28, 29, 32, 33]:
                static_ground_obstacles.add((x, y))
        for x in range(28, 40):
            static_ground_obstacles.add((x, 27)) # Plateau wall/cliff edge

        # Column 17 solid tree wall (Rows 28 to 34)
        for y in range(28, 35):
            static_ground_obstacles.add((17, y))

    elif map_id == "0_220": # Center
        for x in range(13, 15):
            static_ground_obstacles.add((x, 22))
        static_ground_obstacles.add((15, 24))
        for x in range(0, 18):
            static_ground_obstacles.add((x, 15))
            static_ground_obstacles.add((x, 16))
        for x in range(22, 28):
            static_ground_obstacles.add((x, 9))
        for x in range(8, 22):
            for y in range(8, 14):
                static_ground_obstacles.add((x, y))

    start_states = []
    if is_plateau_tile(start_x, start_y):
        start_states.append((start_x, start_y, 1))
    if (start_x, start_y) not in static_ground_obstacles:
        start_states.append((start_x, start_y, 0))

    grass_tiles = set()
    if map_id == "0_219": # West
        for y in range(18, 21):
            grass_tiles.add((3, y))

    queue = []
    for sz in start_states:
        heapq.heappush(queue, (0, start_x, start_y, sz[2], []))

    visited = {}

    # Global symmetrical stairs transitions dictionary
    # format: ((cx, cy, cz), (nx, ny, nz))
    transitions = set()
    if map_id == "0_218":
        transitions = {
            ((22, 24, 0), (22, 23, 1)),
            ((22, 23, 1), (22, 24, 0)),
            ((16, 28, 0), (16, 27, 1)),
            ((16, 27, 1), (16, 28, 0)),
            ((28, 28, 0), (28, 27, 1)),
            ((28, 27, 1), (28, 28, 0)),
            ((34, 14, 0), (34, 15, 1)),
            ((34, 15, 1), (34, 14, 0))
        }
    elif map_id == "0_219":
        transitions = {
            ((6, 20, 0), (6, 19, 1)),
            ((6, 19, 1), (6, 20, 0)),
            ((21, 18, 0), (21, 17, 1)),
            ((21, 17, 1), (21, 18, 0))
        }
    elif map_id == "0_217":
        transitions = {
            ((20, 22, 0), (20, 21, 1)),
            ((20, 21, 1), (20, 22, 0)),
            ((10, 20, 0), (11, 20, 1)),
            ((11, 20, 1), (10, 20, 0)),
            ((12, 8, 0), (12, 7, 1)),
            ((12, 7, 1), (12, 8, 0)),
            ((17, 8, 0), (17, 7, 1)),
            ((17, 7, 1), (17, 8, 0))
        }

    while queue:
        cost, cx, cy, cz, path = heapq.heappop(queue)

        if (cx, cy) == (target_x, target_y):
            return path

        state_key = (cx, cy, cz)
        if state_key in visited and visited[state_key] <= cost:
            continue
        visited[state_key] = cost

        moves = [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]
        for dx, dy, move in moves:
            nx, ny, nz = cx + dx, cy + dy, cz

            # Symmetrical transition check
            is_trans = False
            if ((cx, cy, cz), (nx, ny, 1)) in transitions:
                nz = 1
                is_trans = True
            elif ((cx, cy, cz), (nx, ny, 0)) in transitions:
                nz = 0
                is_trans = True

            if not (0 <= nx < width and 0 <= ny < height):
                continue

            if nz == 0:
                if is_plateau_tile(nx, ny) and not is_trans:
                    continue
                if (nx, ny) in static_ground_obstacles:
                    continue
            else:
                if not is_plateau_tile(nx, ny) and not is_trans:
                    continue

            # Check if transition/tile is blocked by fence on plateau or ground level
            if map_id == "0_218":
                if (nx, ny) in [(36, y) for y in range(15, 24)]:
                    continue

            move_cost = 10 if (nx, ny) in grass_tiles else 1
            heapq.heappush(queue, (cost + move_cost, nx, ny, nz, path + [move]))

    return None

path = solve_safari_path(map_id, start_x, start_y, target_x, target_y)
if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
